package steps

import "testing"

func TestV105ConfigAudit(t *testing.T) {
	t.Parallel()
	runStepCases(t, 105, []stepCase{
		{"bars' location became edge", `{"Bars":{"items":[{"id":"a","location":"top","size":3}]}}`,
			`{"Bars":{"items":[{"id":"a","edge":"top","size":3}]}}`, true},
		{"Network showName", `{"Bars":{"items":[{"left":[{"type":"Network","properties":{"showName":true}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Network","properties":{"showDevice":true}}]}]}}`, true},
		{"Login showAvatar in a module host", `{"Overlay":{"items":[{"layout":[{"type":"Login","properties":{"showAvatar":false}}]}]}}`,
			`{"Overlay":{"items":[{"layout":[{"type":"Login","properties":{"showPicture":false}}]}]}}`, true},
		{"Bluetooth thresholds", `{"Bluetooth":{"lowBattery":20,"criticalBattery":10}}`,
			`{"Bluetooth":{"lowThreshold":20,"criticalThreshold":10}}`, true},
		{"Updates manyThreshold and manyColor", `{"Bars":{"items":[{"right":[{"type":"Updates","properties":{"manyThreshold":50,"manyColor":"base08"}}]}]}}`,
			`{"Bars":{"items":[{"right":[{"type":"Updates","properties":{"warnThreshold":50,"warnColor":"base08"}}]}]}}`, true},
		{"the smallest off-default interval wins, widgets and modules",
			`{"Bars":{"items":[{"left":[{"type":"Updates","properties":{"interval":900000}},{"type":"Updates","properties":{"interval":600000}},{"type":"Updates","properties":{"interval":1800000}}]}]},"Desktop":{"modules":[{"type":"Updates","properties":{"interval":3600000}},{"type":"Updates","properties":{"interval":1200000}}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Updates","properties":{}},{"type":"Updates","properties":{}},{"type":"Updates","properties":{}}]}]},"Desktop":{"modules":[{"type":"Updates","properties":{}},{"type":"Updates","properties":{}}]},"Updates":{"interval":600000}}`, true},
		{"a module's smaller interval beats a widget's",
			`{"Bars":{"items":[{"left":[{"type":"Updates","properties":{"interval":900000}}]}]},"Lockscreen":{"layout":[{"type":"Updates","properties":{"interval":300000}}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Updates","properties":{}}]}]},"Lockscreen":{"layout":[{"type":"Updates","properties":{}}]},"Updates":{"interval":300000}}`, true},
		{"only defaults: the section's stays", `{"Bars":{"items":[{"left":[{"type":"Updates","properties":{"interval":1800000}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Updates","properties":{}}]}]}}`, true},
		{"an existing Updates.interval is kept", `{"Updates":{"interval":300000},"Bars":{"items":[{"left":[{"type":"Updates","properties":{"interval":600000}}]}]}}`,
			`{"Updates":{"interval":300000},"Bars":{"items":[{"left":[{"type":"Updates","properties":{}}]}]}}`, true},
		{"noWarps true", `{"WindowBehaviour":{"noWarps":true}}`, `{"WindowBehaviour":{"warpCursor":false}}`, true},
		{"noWarps false", `{"WindowBehaviour":{"noWarps":false}}`, `{"WindowBehaviour":{"warpCursor":true}}`, true},
		{"warpCursor already present", `{"WindowBehaviour":{"noWarps":true,"warpCursor":true}}`, `{"WindowBehaviour":{"warpCursor":true}}`, true},
		{"Workspaces textColor", `{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"spacing":2,"textColor":"base05"}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"spacing":2,"foregroundColor":"base05"}}]}]}}`, true},
		{"Workspaces keep and hide", `{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"activeWorkspaceIcons":"keep"}},{"type":"Workspaces","properties":{"activeWorkspaceIcons":"hide"}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"activeWorkspaceIcons":true}},{"type":"Workspaces","properties":{"activeWorkspaceIcons":false}}]}]}}`, true},
		{"Workspaces icon head without leadIcon", `{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"lead":"icon"}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"leadIcon":"grid_view"}}]}]}}`, true},
		{"Workspaces icon head with leadIcon", `{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"lead":"icon","leadIcon":"star"}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"leadIcon":"star"}}]}]}}`, true},
		{"Workspaces none, active and position heads", `{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"lead":"none","leadIcon":"star"}},{"type":"Workspaces","properties":{"lead":"active"}},{"type":"Workspaces","properties":{"lead":"position","leadIcon":"x"}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"leadIcon":""}},{"type":"Workspaces","properties":{"leadIcon":""}},{"type":"Workspaces","properties":{"leadIcon":""}}]}]}}`, true},
		{"Workspaces showActiveIcon dropped", `{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"showActiveIcon":true,"spacing":1}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Workspaces","properties":{"spacing":1}}]}]}}`, true},
		{"Time none became auto", `{"Bars":{"items":[{"left":[{"type":"Time","properties":{"lead":"none"}},{"type":"Time","properties":{"lead":"icon"}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Time","properties":{"lead":"auto"}},{"type":"Time","properties":{"lead":"icon"}}]}]}}`, true},
		{"OSD tiles, keys and kinds became shows", `{"OSD":{"items":[{"systems":[{"type":"Battery","tiles":["a"]},{"type":"Audio","tiles":["v"]},{"type":"LockKeys","keys":["caps"]},{"type":"Privacy","kinds":["mic"]},{"type":"Other","tiles":["z"]}]}]}}`,
			`{"OSD":{"items":[{"systems":[{"type":"Battery","shows":["a"]},{"type":"Audio","shows":["v"]},{"type":"LockKeys","shows":["caps"]},{"type":"Privacy","shows":["mic"]},{"type":"Other","tiles":["z"]}]}]}}`, true},
		{"Media idleText No player", `{"Bars":{"items":[{"left":[{"type":"Media","properties":{"idleText":"No player"}},{"type":"Media","properties":{"idleText":"Quiet"}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Media","properties":{"idleText":""}},{"type":"Media","properties":{"idleText":"Quiet"}}]}]}}`, true},
		{"appearance.width 0 became null, in a group and CustomWidgets",
			`{"Bars":{"items":[{"left":[{"type":"Clock","properties":{"appearance":{"width":0}}},{"type":"Group","properties":{"widgets":[{"type":"Clock","properties":{"appearance":{"width":0}}},{"type":"Clock","properties":{"appearance":{"width":40}}}]}}]}]},"CustomWidgets":{"items":[{"bar":{"width":0}}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Clock","properties":{"appearance":{"width":null}}},{"type":"Group","properties":{"widgets":[{"type":"Clock","properties":{"appearance":{"width":null}}},{"type":"Clock","properties":{"appearance":{"width":40}}}]}}]}]},"CustomWidgets":{"items":[{"bar":{"width":null}}]}}`, true},
		{"a widget nested in a group", `{"Bars":{"items":[{"left":[{"type":"Group","properties":{"widgets":[{"type":"Network","properties":{"showName":true}}]}}]}]}}`,
			`{"Bars":{"items":[{"left":[{"type":"Group","properties":{"widgets":[{"type":"Network","properties":{"showDevice":true}}]}}]}]}}`, true},
		{"Interface.radius moved", `{"Interface":{"radius":8}}`, `{"Interface":{},"Appearance":{"shape":{"innerRadius":8}}}`, true},
		{"WindowLook.surfaceBlur moved", `{"WindowLook":{"surfaceBlur":{"enabled":true}}}`,
			`{"WindowLook":{},"Appearance":{"surface":{"blur":{"enabled":true}}}}`, true},
		{"sway specialWorkspaces moved", `{"Compositor":{"sway":{"specialWorkspaces":"hide"}}}`,
			`{"Compositor":{"sway":{}},"Workspaces":{"specialWorkspaces":"hide"}}`, true},
		{"apps timeout 0 became null", `{"Notifications":{"apps":[{"app":"x","timeout":0},{"app":"y","timeout":5000}]}}`,
			`{"Notifications":{"apps":[{"app":"x","timeout":null},{"app":"y","timeout":5000}]}}`, true},
		{"rounding: off-step, under half a unit, zero",
			`{"Pomodoro":{"work":1500001,"shortBreak":10000,"longBreak":0}}`,
			`{"Pomodoro":{"work":1500000,"shortBreak":60000,"longBreak":0}}`, true},
		{"rounding: a value on its step", `{"Pomodoro":{"work":1500000}}`, `{"Pomodoro":{"work":1500000}}`, false},
		{"nothing", `{"General":{}}`, `{"General":{}}`, false},
	})
}
